#include <bits/stdc++.h>
using namespace std;

long long silnia(int n) {
    if (n <= 1) return 1;                 // warunek stopu
    return n * silnia(n - 1);             // krok: n! = n * (n-1)!
}

long long potega(long long a, int n) {    // a^n w O(n)
    if (n == 0) return 1;
    return a * potega(a, n - 1);
}

long long szybkaPotega(long long a, long long n) {   // a^n w O(log n)
    if (n == 0) return 1;
    long long h = szybkaPotega(a, n / 2);            // licz RAZ, użyj dwa razy
    if (n % 2 == 0) return h * h;
    return h * h * a;
}

long long fib(int n) {                    // O(1.62^n) — wykładniczo wolne!
    if (n < 2) return n;                  // fib(0) = 0, fib(1) = 1
    return fib(n - 1) + fib(n - 2);
}

int sumaCyfr(int n) {
    if (n < 10) return n;
    return n % 10 + sumaCyfr(n / 10);
}

int main() {
    cout << silnia(10) << '\n';           // 3628800
    cout << potega(2, 10) << '\n';        // 1024
    cout << szybkaPotega(3, 20) << '\n';  // 3486784401
    cout << fib(20) << '\n';              // 6765
    cout << sumaCyfr(2024) << '\n';       // 8
}

long long memo[95];
